  n_q: "{K}: g = {g} N/kg. كتلة رائدة فضاء مع بدلتها {m} kg. ما قوة وزنها هناك؟ (بالنيوتن، مقرّبة لعدد صحيح)",
  c_name: "ماري كوري", c_zeit: "1867–1934", c_kurz: "عمر النصف: ما سرعة تحلّل المادة المشعّة؟",
  c_story: "نشأت ماري سكوودوفسكا كوري في وارسو وأجرت أبحاثها في باريس. اكتشفت مع زوجها بيير عنصري البولونيوم والراديوم ودرست النشاط الإشعاعي – والكلمة من وضعها. نالت جائزتي نوبل في الفيزياء (1903) والكيمياء (1911)، وما زالت الشخص الوحيد الذي فاز بها في علمين طبيعيين مختلفين. تتحلّل المواد المشعّة وفق قاعدة ثابتة: في كل عمر نصف يتحلّل نصف الذرات الباقية.",
  c_weiter: "عمر نصف آخر", c_reset: "من البداية", c_noch: "أعمار النصف: {n} · بقي {a} من 100 ذرة", c_erwartet: "القاعدة: 100 · (½)^{n} = {e}",
