  te_q: "لمحوّل {N1} لفّة في جهة الدخل و{N2} لفّة في جهة الخرج. جهد الدخل {U1} V. ما جهد الخرج (بالفولت)؟",
  tu_name: "آلان تورنغ", tu_zeit: "1912–1954", tu_kurz: "آلة تورنغ: حاسوب من شريط وقواعد",
  tu_story: "كان آلان تورنغ عالم رياضيات بريطانيًا. في عام 1936 تخيّل آلة بسيطة جدًا: رأس قراءة على شريط طويل من الرموز يقرأ ويكتب ويتحرك وفق قواعد ثابتة. وأثبت أن «آلة تورنغ» هذه تستطيع حساب كل ما يمكن حسابه أصلًا – وهي الفكرة التي يقوم عليها كل حاسوب. وفي الحرب العالمية الثانية ساعد في بلتشلي بارك على فكّ رسائل آلة إنيغما الألمانية المشفّرة.",
  tu_zahl: "العدد بالنظام الثنائي:", tu_schritt: "خطوة واحدة", tu_auto: "نفّذ حتى النهاية", tu_reset: "من جديد", tu_zustand: "الحالة", tu_regeln: "قواعد الآلة «+1»",
  tu_r1: "تقرأ 1 ← تكتب 0 وتتحرك خانة إلى اليسار", tu_r2: "تقرأ 0 أو خانة فارغة ← تكتب 1 وتنتهي",
  tu_laeuft: "تحسب", tu_halt: "انتهت", tu_fertig: "انتهت! {a} + 1 = {b}",
  tu_bin: "الأعداد الثنائية تتكوّن من 0 و1 فقط. كل خانة قيمتها ضعف قيمة الخانة التي على يمينها: 1، 2، 4، 8، 16 …",
  tu_ungueltig: "أدخل 0 و1 فقط (12 خانة على الأكثر).",
  tu_q1: "ما العدد العشري الذي يساوي العدد الثنائي {b}؟", tu_q2: "تحصل الآلة «+1» على العدد الثنائي {b}. ما العدد العشري الموجود على الشريط في النهاية؟",
  f_name: "مبرهنة الألوان الأربعة", f_zeit: "غوثري 1852 · أبيل وهاكن 1976", f_kurz: "كل خريطة تكفيها 4 ألوان",
  f_story: "في عام 1852 كان الطالب فرانسيس غوثري يلوّن خريطة مقاطعات إنجلترا فلاحظ أن أربعة ألوان تكفي كي لا تتشابه ألوان المناطق المتجاورة أبدًا. فهل يصحّ ذلك لكل خريطة؟ بحث علماء الرياضيات أكثر من 100 عام عن برهان، ولم ينجح في ذلك إلا كينيث أبيل وفولفغانغ هاكن عام 1976 – بمساعدة حاسوب فحص قرابة 2000 حالة خاصة. وكان من أوائل البراهين الكبيرة بمساعدة الحاسوب. والبلدان التي تتلامس في نقطة واحدة فقط لا تُعدّ متجاورة.",
  f_anl: "اختر لونًا ثم اضغط على البلدان. لا يجوز أن يكون لبلدين متجاورين اللون نفسه. هل تنجح بأربعة ألوان – أو حتى بثلاثة؟",
